import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 첨부파일의 소유 대상 유형 값 (값 목록 미확정)
const OWNER_APPROVAL = 'approval_document';
const OWNER_POST = 'post';
const CATEGORIES = ['전자결재', '게시판', '일정관리', '문서함'];
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

// 가정: 열람 범위는 문서의 공개 설정과 작성자 기준으로 제한한다 (공통 권한 규칙은 공통 모듈이 맡는다)
const APPROVAL_VISIBLE = '(approval_document.is_secret = false OR approval_document.drafter_id = CAST(:userId AS bigint))';
const POST_VISIBLE = `(post.visibility_scope = 'ALL'
  OR post.author_id = CAST(:userId AS bigint)
  OR (post.visibility_scope = 'DEPARTMENT' AND EXISTS (
    SELECT 1 FROM employee AS author
    JOIN employee AS viewer ON viewer.department_id = author.department_id
    WHERE author.employee_id = post.author_id
    AND viewer.employee_id = CAST(:userId AS bigint))))`;

interface ResultRow {
  resultId: number;
  title: string;
  attachmentId?: number | null;
  fileName?: string | null;
}

@Controller('api/v1')
export class FnSfr03901Controller {
  @Get('/integrated-searches')
  async searchIntegrated(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const query = checks.queryOf(req.query);
    const keyword = typeof query['keyword'] === 'string' ? query['keyword'].trim() : '';
    if (keyword === '') {
      throw new ApiError(422, 'SEARCH_KEYWORD_REQUIRED', '검색어를 입력해 주세요.');
    }
    const category = query['category'] ? String(query['category']) : '';
    if (category !== '' && !CATEGORIES.includes(category)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '카테고리가 올바르지 않습니다.');
    }
    const pageText = query['page'] === undefined || query['page'] === '' ? '0' : String(query['page']);
    const sizeText = query['size'] === undefined || query['size'] === '' ? String(DEFAULT_SIZE) : String(query['size']);
    if (!/^\d+$/.test(pageText) || !/^\d+$/.test(sizeText)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호나 크기가 올바르지 않습니다.');
    }
    const page = Number(pageText);
    const size = Math.min(Math.max(Number(sizeText), 1), MAX_SIZE);
    const includeAttachments = String(query['includeAttachments'] ?? '') === 'true';
    const limit = (page + 1) * size;
    const targets = category === '' ? CATEGORIES : [category];

    return transaction(async (db) => {
      const params = { keyword, userId: user.id, limit, ownerApproval: OWNER_APPROVAL, ownerPost: OWNER_POST };
      const all: { category: string; count: number; row: ResultRow }[] = [];
      let total = 0;

      for (const name of targets) {
        let rows: ResultRow[] = [];
        let count = 0;
        if (name === '전자결재') {
          const where = `(approval_document.title ILIKE '%' || :keyword || '%' OR approval_document.body ILIKE '%' || :keyword || '%') AND ${APPROVAL_VISIBLE}`;
          const counted = await db.query(`SELECT COUNT(*) AS "total" FROM approval_document WHERE ${where}`, params);
          count = Number(counted[0]['total']);
          rows = await db.query(
            `SELECT approval_document.approval_document_id AS "resultId", approval_document.title AS "title"
             FROM approval_document WHERE ${where}
             ORDER BY approval_document.approval_document_id DESC LIMIT CAST(:limit AS integer)`,
            params,
          );
          if (includeAttachments) {
            const fileWhere = `attachment.owner_type = :ownerApproval AND attachment.file_name ILIKE '%' || :keyword || '%' AND ${APPROVAL_VISIBLE}`;
            const fileCounted = await db.query(
              `SELECT COUNT(*) AS "total" FROM attachment JOIN approval_document ON approval_document.approval_document_id = attachment.owner_id WHERE ${fileWhere}`,
              params,
            );
            count += Number(fileCounted[0]['total']);
            const fileRows = await db.query(
              `SELECT approval_document.approval_document_id AS "resultId", approval_document.title AS "title",
                      attachment.attachment_id AS "attachmentId", attachment.file_name AS "fileName"
               FROM attachment JOIN approval_document ON approval_document.approval_document_id = attachment.owner_id
               WHERE ${fileWhere}
               ORDER BY attachment.attachment_id DESC LIMIT CAST(:limit AS integer)`,
              params,
            );
            rows = rows.concat(fileRows);
          }
        } else if (name === '게시판') {
          const where = `(post.title ILIKE '%' || :keyword || '%' OR post.content ILIKE '%' || :keyword || '%') AND ${POST_VISIBLE}`;
          const counted = await db.query(`SELECT COUNT(*) AS "total" FROM post WHERE ${where}`, params);
          count = Number(counted[0]['total']);
          rows = await db.query(
            `SELECT post.post_id AS "resultId", post.title AS "title"
             FROM post WHERE ${where}
             ORDER BY post.post_id DESC LIMIT CAST(:limit AS integer)`,
            params,
          );
          if (includeAttachments) {
            const fileWhere = `attachment.owner_type = :ownerPost AND attachment.file_name ILIKE '%' || :keyword || '%' AND ${POST_VISIBLE}`;
            const fileCounted = await db.query(
              `SELECT COUNT(*) AS "total" FROM attachment JOIN post ON post.post_id = attachment.owner_id WHERE ${fileWhere}`,
              params,
            );
            count += Number(fileCounted[0]['total']);
            const fileRows = await db.query(
              `SELECT post.post_id AS "resultId", post.title AS "title",
                      attachment.attachment_id AS "attachmentId", attachment.file_name AS "fileName"
               FROM attachment JOIN post ON post.post_id = attachment.owner_id
               WHERE ${fileWhere}
               ORDER BY attachment.attachment_id DESC LIMIT CAST(:limit AS integer)`,
              params,
            );
            rows = rows.concat(fileRows);
          }
        } else {
          // TODO(질문): 일정관리·문서함은 schema.sql에 검색할 테이블이 없어 구현하지 못했다.
          continue;
        }
        total += count;
        for (const row of rows) {
          all.push({ category: name, count, row });
        }
      }

      const start = page * size;
      const items = all.slice(start, start + size).map((entry) => ({
        category: entry.category,
        count: entry.count,
        resultId: Number(entry.row.resultId),
        title: entry.row.title,
        attachmentId: entry.row.attachmentId == null ? null : Number(entry.row.attachmentId),
        fileName: entry.row.fileName ?? null,
      }));
      return { items, page, size, total };
    });
  }
}

