import { useState } from 'react';
import { call, useData, Tiles, Filters, Field, TextInput, Select, Band, DataTable, Pager, Drawer, Pairs, ErrorText } from '../kit';
import type { PageProps, Row, Page } from '../kit';

const CATEGORY_OPTIONS: [string, string][] = [
  ['전자결재', '전자결재'],
  ['게시판', '게시판'],
  ['일정관리', '일정관리'],
  ['문서함', '문서함'],
];

const ATTACHMENT_OPTIONS: [string, string][] = [
  ['true', '포함'],
  ['false', '제외'],
];

export default function FnSfr03901Page({ role, notify }: PageProps) {
  const [keyword, setKeyword] = useState('');
  const [category, setCategory] = useState('');
  const [includeAttachments, setIncludeAttachments] = useState('false');
  const [applied, setApplied] = useState<Row | null>(null);
  const [page, setPage] = useState(0);
  const [selected, setSelected] = useState<Row | null>(null);
  const [message, setMessage] = useState('');

  const { data, error, loading } = useData<Page | undefined>(async () => {
    if (!applied) return undefined;
    return call<Page>('GET', '/integrated-searches', role, undefined, { ...applied, page });
  }, [applied, page, role]);

  function search() {
    if (keyword.trim() === '') {
      setMessage('검색어를 입력해 주세요.');
      return;
    }
    setMessage('');
    setPage(0);
    setApplied({ keyword: keyword.trim(), category, includeAttachments });
  }

  function reset() {
    setKeyword('');
    setCategory('');
    setIncludeAttachments('false');
    setApplied(null);
    setMessage('');
    setPage(0);
  }

  const rows = data ? data.items : [];
  const counts: Record<string, unknown> = {};
  for (const row of rows) {
    counts[String(row.category)] = row.count;
  }
  const tiles: [string, React.ReactNode][] = Object.keys(counts).map((name) => [name, String(counts[name]) + '건']);

  return (
    <div className="bento">
      {tiles.length > 0 && (
        <section className="box span-12">
          <h2>카테고리별 결과</h2>
          <Tiles items={tiles.slice(0, 4)} />
        </section>
      )}
      <section className="box span-12">
        <h2>통합검색</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="검색어" required>
            <TextInput value={keyword} onChange={setKeyword} placeholder="검색어를 입력하세요" />
          </Field>
          <Field label="카테고리">
            <Select value={category} onChange={setCategory} options={CATEGORY_OPTIONS} placeholder="전체" />
          </Field>
          <Field label="첨부파일 내용 검색 포함 여부">
            <Select value={includeAttachments} onChange={setIncludeAttachments} options={ATTACHMENT_OPTIONS} placeholder="제외" />
          </Field>
        </Filters>
        {message !== '' && <ErrorText text={message} />}
        {error !== '' && <ErrorText text={error} />}
        <Band total={data ? data.total : 0} />
        <DataTable
          columns={[
            { key: 'category', label: '검색 결과 카테고리' },
            { key: 'title', label: '결과 제목' },
            { key: 'fileName', label: '파일명' },
          ]}
          rows={rows}
          onRowClick={(row) => setSelected(row)}
          empty={loading ? '검색 중입니다.' : applied ? '검색 결과가 없습니다.' : '검색어를 입력하고 조회하세요.'}
        />
        {data && <Pager page={data.page} size={data.size} total={data.total} onPage={setPage} />}
      </section>
      {selected && (
        <Drawer title="검색 결과 상세" onClose={() => setSelected(null)}>
          <Pairs
            items={[
              ['검색 결과 카테고리', String(selected.category)],
              ['카테고리별 결과 건수', String(selected.count)],
              ['결과 항목 ID', String(selected.resultId)],
              ['결과 제목', String(selected.title)],
              ['파일명', selected.fileName ? String(selected.fileName) : '-'],
            ]}
          />
        </Drawer>
      )}
    </div>
  );
}
